declare_lint ! { #[doc = " The `const_item_interior_mutations` lint checks for calls which"] #[doc = " mutates an interior mutable const-item."] #[doc = ""] #[doc = " ### Example"] #[doc = ""] #[doc = " ```rust"] #[doc = " use std::sync::Once;"] #[doc = ""] #[doc = " const INIT: Once = Once::new(); // using `INIT` will always create a temporary and"] #[doc = "                                 // never modify it-self on use, should be a `static`"] #[doc = "                                 // instead for shared use"] #[doc = ""] #[doc = " fn init() {"] #[doc = "     INIT.call_once(|| {"] #[doc = "         println!(\"Once::call_once first call\");"] #[doc = "     });"] #[doc = "     INIT.call_once(|| {                          // this second will also print"] #[doc = "         println!(\"Once::call_once second call\"); // as each call to `INIT` creates"] #[doc = "     });                                          // new temporary"] #[doc = " }"] #[doc = " ```"] #[doc = ""] #[doc = " {{produces}}"] #[doc = ""] #[doc = " ### Explanation"] #[doc = ""] #[doc = " Calling a method which mutates an interior mutable type has no effect as const-item"] #[doc = " are essentially inlined wherever they are used, meaning that they are copied"] #[doc = " directly into the relevant context when used rendering modification through"] #[doc = " interior mutability ineffective across usage of that const-item."] #[doc = ""] #[doc = " The current implementation of this lint only warns on significant `std` and"] #[doc = " `core` interior mutable types, like `Once`, `AtomicI32`, ... this is done out"] #[doc = " of prudence to avoid false-positive and may be extended in the future."] pub CONST_ITEM_INTERIOR_MUTATIONS , Warn , "checks for calls which mutates a interior mutable const-item" }